-- Procurement readiness uses the existing RRCI workspace and paid/trial entitlement.
-- RegulaOS retains ownership of authoritative obligations; these are scoped evidence records.
BEGIN;
CREATE TABLE public.procurement_packs (
 id text PRIMARY KEY, version text NOT NULL, title text NOT NULL, description text NOT NULL,
 caution text NOT NULL, source_checked_on date NOT NULL, requirements jsonb NOT NULL
 CHECK(jsonb_typeof(requirements)='array')
);
CREATE TABLE public.procurement_assessments (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 workspace_id uuid NOT NULL REFERENCES public.rrci_workspaces(id),
 pack_id text NOT NULL REFERENCES public.procurement_packs(id), pack_version text NOT NULL,
 name text NOT NULL CHECK(length(btrim(name)) BETWEEN 3 AND 160),
 legal_entity text NOT NULL CHECK(length(btrim(legal_entity)) BETWEEN 2 AND 200),
 scope text NOT NULL CHECK(length(btrim(scope)) BETWEEN 10 AND 2000),
 buyer text NOT NULL CHECK(length(btrim(buyer)) BETWEEN 2 AND 200),
 country text NOT NULL CHECK(length(btrim(country)) BETWEEN 2 AND 100),
 created_by uuid NOT NULL REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(id,workspace_id)
);
CREATE TABLE public.procurement_requirements (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL, workspace_id uuid NOT NULL,
 template jsonb NOT NULL CHECK(jsonb_typeof(template)='object'),
 status text NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','in_progress','evidence_ready','reviewed','not_applicable')),
 owner_name text NOT NULL DEFAULT '' CHECK(length(owner_name)<=120), due_date date,
 evidence_title text NOT NULL DEFAULT '' CHECK(length(evidence_title)<=200),
 evidence_url text NOT NULL DEFAULT '' CHECK(length(evidence_url)<=1500 AND (evidence_url='' OR evidence_url ~ '^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$')),
 issuer text NOT NULL DEFAULT '' CHECK(length(issuer)<=200), reference text NOT NULL DEFAULT '' CHECK(length(reference)<=200),
 valid_until date, notes text NOT NULL DEFAULT '' CHECK(length(notes)<=4000),
 review_reason text NOT NULL DEFAULT '' CHECK(length(review_reason)<=2000),
 reviewed_by uuid REFERENCES auth.users(id), reviewed_at timestamptz,
 version integer NOT NULL DEFAULT 1,
 FOREIGN KEY(assessment_id,workspace_id) REFERENCES public.procurement_assessments(id,workspace_id),
 CHECK(status NOT IN ('reviewed','not_applicable') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND length(btrim(review_reason))>=10)),
 CHECK(status<>'reviewed' OR (length(btrim(evidence_title))>0 AND length(evidence_url)>0)),
 CHECK(status<>'reviewed' OR template->>'kind'='readiness' OR (length(btrim(issuer))>0 AND length(btrim(reference))>0))
);
CREATE TABLE public.procurement_audit (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, assessment_id uuid NOT NULL, workspace_id uuid NOT NULL,
 actor uuid NOT NULL REFERENCES auth.users(id), action text NOT NULL, detail jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(assessment_id,workspace_id) REFERENCES public.procurement_assessments(id,workspace_id)
);
CREATE INDEX ON public.procurement_assessments(workspace_id,created_at DESC);
CREATE INDEX ON public.procurement_requirements(workspace_id,assessment_id);
CREATE INDEX ON public.procurement_audit(workspace_id,id DESC);
CREATE FUNCTION public.procurement_can(_workspace uuid,_permission text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT public.rrci_has_access(_workspace) AND EXISTS(
 SELECT 1 FROM public.rrci_members WHERE workspace_id=_workspace AND user_id=auth.uid()
 AND CASE _permission WHEN 'read' THEN true WHEN 'write' THEN role IN ('editor','admin')
 WHEN 'approve' THEN role IN ('reviewer','admin') WHEN 'audit' THEN role IN ('reviewer','admin') ELSE false END);
$$;
REVOKE ALL ON FUNCTION public.procurement_can(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.procurement_can(uuid,text) TO authenticated;
ALTER TABLE public.procurement_packs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_assessments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_requirements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.procurement_packs,public.procurement_assessments,public.procurement_requirements,public.procurement_audit FROM anon,authenticated;
GRANT SELECT ON public.procurement_packs,public.procurement_assessments,public.procurement_requirements,public.procurement_audit TO authenticated;
GRANT ALL ON public.procurement_packs,public.procurement_assessments,public.procurement_requirements,public.procurement_audit TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.procurement_audit_id_seq TO service_role;
CREATE POLICY "read starter packs" ON public.procurement_packs FOR SELECT TO authenticated USING(true);
CREATE POLICY "read own readiness assessments" ON public.procurement_assessments FOR SELECT TO authenticated USING(public.procurement_can(workspace_id,'read'));
CREATE POLICY "read own readiness evidence" ON public.procurement_requirements FOR SELECT TO authenticated USING(public.procurement_can(workspace_id,'read'));
CREATE POLICY "read own readiness audit" ON public.procurement_audit FOR SELECT TO authenticated USING(public.procurement_can(workspace_id,'audit'));

CREATE FUNCTION public.create_procurement_assessment(_workspace uuid,_pack text,_name text,_entity text,_scope text,_buyer text,_country text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE p public.procurement_packs; a uuid;
BEGIN
 IF NOT public.procurement_can(_workspace,'write') THEN RAISE EXCEPTION 'Readiness access denied'; END IF;
 SELECT * INTO STRICT p FROM public.procurement_packs WHERE id=_pack;
 INSERT INTO public.procurement_assessments(workspace_id,pack_id,pack_version,name,legal_entity,scope,buyer,country,created_by)
 VALUES(_workspace,p.id,p.version,btrim(_name),btrim(_entity),btrim(_scope),btrim(_buyer),btrim(_country),auth.uid()) RETURNING id INTO a;
 INSERT INTO public.procurement_requirements(assessment_id,workspace_id,template)
 SELECT a,_workspace,value FROM jsonb_array_elements(p.requirements);
 INSERT INTO public.procurement_audit(assessment_id,workspace_id,actor,action,detail)
 VALUES(a,_workspace,auth.uid(),'assessment.created',jsonb_build_object('pack',p.id,'version',p.version));
 RETURN a;
END; $$;

CREATE FUNCTION public.save_procurement_requirement(_id uuid,_version integer,_changes jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.procurement_requirements; updated public.procurement_requirements;
BEGIN
 SELECT * INTO r FROM public.procurement_requirements WHERE id=_id FOR UPDATE;
 IF NOT FOUND OR NOT public.procurement_can(r.workspace_id,'write') THEN RAISE EXCEPTION 'Readiness access denied'; END IF;
 IF _version IS NULL OR r.version<>_version THEN RAISE EXCEPTION 'This item changed. Reload before saving.'; END IF;
 IF jsonb_typeof(_changes) IS DISTINCT FROM 'object' OR _changes->>'status' IS NULL OR _changes->>'status' NOT IN ('not_started','in_progress','evidence_ready')
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(_changes) k WHERE k NOT IN ('status','owner_name','due_date','evidence_title','evidence_url','issuer','reference','valid_until','notes'))
 THEN RAISE EXCEPTION 'Invalid evidence update'; END IF;
 UPDATE public.procurement_requirements SET status=_changes->>'status',
 owner_name=coalesce(btrim(_changes->>'owner_name'),''),due_date=nullif(_changes->>'due_date','')::date,
 evidence_title=coalesce(btrim(_changes->>'evidence_title'),''),evidence_url=coalesce(btrim(_changes->>'evidence_url'),''),
 issuer=coalesce(btrim(_changes->>'issuer'),''),reference=coalesce(btrim(_changes->>'reference'),''),
 valid_until=nullif(_changes->>'valid_until','')::date,notes=coalesce(btrim(_changes->>'notes'),''),
 reviewed_by=NULL,reviewed_at=NULL,review_reason='',version=version+1 WHERE id=_id RETURNING * INTO updated;
 IF updated.status='evidence_ready' AND (updated.evidence_title='' OR updated.evidence_url='') THEN RAISE EXCEPTION 'Add an evidence title and secure link before review'; END IF;
 INSERT INTO public.procurement_audit(assessment_id,workspace_id,actor,action,detail)
 VALUES(r.assessment_id,r.workspace_id,auth.uid(),'evidence.saved',jsonb_build_object('requirement',_id,'before',to_jsonb(r),'after',to_jsonb(updated)));
END; $$;

CREATE FUNCTION public.review_procurement_requirement(_id uuid,_version integer,_decision text,_reason text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.procurement_requirements;
BEGIN
 SELECT * INTO r FROM public.procurement_requirements WHERE id=_id FOR UPDATE;
 IF NOT FOUND OR NOT public.procurement_can(r.workspace_id,'approve') THEN RAISE EXCEPTION 'Reviewer access required'; END IF;
 IF _version IS NULL OR r.version<>_version THEN RAISE EXCEPTION 'This item changed. Reload before reviewing.'; END IF;
 IF _decision IS NULL OR _decision NOT IN ('reviewed','not_applicable','in_progress') OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Choose a review decision and give a reason of at least 10 characters'; END IF;
 IF _decision='not_applicable' AND coalesce((r.template->>'mandatory')::boolean,false) THEN RAISE EXCEPTION 'This assessment milestone cannot be excluded'; END IF;
 IF _decision='reviewed' AND (r.status<>'evidence_ready' OR r.evidence_title='' OR r.evidence_url='' OR r.valid_until < (now() AT TIME ZONE 'UTC')::date) THEN RAISE EXCEPTION 'Current evidence must be submitted before internal review'; END IF;
 IF _decision='reviewed' AND r.template->>'key'='aramco-ccc-plus-15' AND r.valid_until IS NULL THEN RAISE EXCEPTION 'Record the CCC+ certificate expiry date'; END IF;
 IF _decision='reviewed' AND r.template->>'kind'<>'readiness' AND (r.issuer='' OR r.reference='') THEN RAISE EXCEPTION 'Record the actual issuer or buyer and reference'; END IF;
 UPDATE public.procurement_requirements SET status=_decision,review_reason=btrim(_reason),reviewed_by=auth.uid(),reviewed_at=now(),version=version+1 WHERE id=_id;
 INSERT INTO public.procurement_audit(assessment_id,workspace_id,actor,action,detail)
 VALUES(r.assessment_id,r.workspace_id,auth.uid(),'requirement.reviewed',jsonb_build_object('requirement',_id,'previous_status',r.status,'decision',_decision,'reason',btrim(_reason),'version',r.version+1));
END; $$;

CREATE FUNCTION public.add_procurement_requirement(_assessment uuid,_template jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.procurement_assessments; item uuid;
BEGIN
 SELECT * INTO a FROM public.procurement_assessments WHERE id=_assessment;
 IF NOT FOUND OR NOT public.procurement_can(a.workspace_id,'write') THEN RAISE EXCEPTION 'Readiness access denied'; END IF;
 IF jsonb_typeof(_template) IS DISTINCT FROM 'object'
 OR coalesce(length(btrim(_template->>'title')),0) NOT BETWEEN 3 AND 200
 OR coalesce(_template->>'kind','') NOT IN ('readiness','registration','certification','buyer_decision')
 OR coalesce(length(btrim(_template->>'applies_when')),0) NOT BETWEEN 3 AND 1000
 OR coalesce(length(btrim(_template->>'guidance')),0) NOT BETWEEN 3 AND 2000
 OR coalesce(length(btrim(_template->>'evidence')),0) NOT BETWEEN 3 AND 1000
 OR coalesce(_template->>'source_url','') !~ '^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$'
 OR length(_template->>'source_url')>1500 THEN RAISE EXCEPTION 'Provide a complete requirement and secure source link'; END IF;
 INSERT INTO public.procurement_requirements(assessment_id,workspace_id,template)
 VALUES(a.id,a.workspace_id,jsonb_build_object('key',gen_random_uuid()::text,'category','Buyer-specific','title',_template->>'title','kind',_template->>'kind',
 'applies_when',_template->>'applies_when','guidance',_template->>'guidance','evidence',_template->>'evidence','source_url',_template->>'source_url')) RETURNING id INTO item;
 INSERT INTO public.procurement_audit(assessment_id,workspace_id,actor,action,detail)
 VALUES(a.id,a.workspace_id,auth.uid(),'requirement.added',jsonb_build_object('requirement',item,'template',_template));
 RETURN item;
END; $$;

CREATE FUNCTION public.record_procurement_export(_assessment uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.procurement_assessments;
BEGIN
 SELECT * INTO a FROM public.procurement_assessments WHERE id=_assessment;
 IF NOT FOUND OR NOT public.procurement_can(a.workspace_id,'read') THEN RAISE EXCEPTION 'Readiness access denied'; END IF;
 INSERT INTO public.procurement_audit(assessment_id,workspace_id,actor,action,detail)
 VALUES(a.id,a.workspace_id,auth.uid(),'dossier.exported','{"format":"json","private_evidence_links":false}'::jsonb);
END; $$;

REVOKE ALL ON FUNCTION public.create_procurement_assessment(uuid,text,text,text,text,text,text),public.save_procurement_requirement(uuid,integer,jsonb),public.review_procurement_requirement(uuid,integer,text,text),public.add_procurement_requirement(uuid,jsonb),public.record_procurement_export(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_procurement_assessment(uuid,text,text,text,text,text,text),public.save_procurement_requirement(uuid,integer,jsonb),public.review_procurement_requirement(uuid,integer,text,text),public.add_procurement_requirement(uuid,jsonb),public.record_procurement_export(uuid) TO authenticated;

-- Versioned starter packs; existing assessments retain snapshots.
INSERT INTO public.procurement_packs(id,version,title,description,caution,source_checked_on,requirements) VALUES ('aramco-ccc-plus','2026-09-16.1','Aramco CCC+ cybersecurity','Priority pathway for CCC+ preparation, on-site assessment and certificate evidence.','Confirm the route with Aramco or an authorised audit firm. This is a preparation checklist, not the complete SACS-210 control register. Add every applicable control before review. Core assessment milestones cannot be excluded. Only an authorised firm issues CCC+.','2026-09-16','[{"key": "aramco-ccc-plus-01", "title": "Confirmed CCC+ classification", "category": "Scope", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Obtain written classification and CCC+ route confirmation. Resolve Network Connectivity guidance with the assessor.", "evidence": "Classification and route confirmation", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "aramco-ccc-plus-02", "title": "Complete scoped control register", "category": "Scope", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Map every applicable SACS-210 control, including all overlapping classifications, into this assessment.", "evidence": "Assessor-reviewed coverage matrix", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-03", "title": "Governance and accountable owners", "category": "Governance", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Assign implementation and evidence owners.", "evidence": "Approved policies and responsibilities", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-04", "title": "Asset and data boundary", "category": "Identify", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Document systems, locations, services and data.", "evidence": "Current inventories and diagrams", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-05", "title": "Identity and privileged access", "category": "Protect", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Gather access, MFA and account-review evidence.", "evidence": "Configurations and review records", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-06", "title": "Endpoint, email and network protection", "category": "Protect", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Evidence the safeguards applicable to your environment.", "evidence": "Dated technical evidence", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-07", "title": "Vulnerability and patch handling", "category": "Protect", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Track findings and remediation.", "evidence": "Test results and closure records", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-08", "title": "Data protection and lifecycle", "category": "Protect", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Evidence handling, encryption and disposal controls.", "evidence": "Operating records", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-09", "title": "Monitoring and incident preparedness", "category": "Detect and respond", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Demonstrate monitoring and incident processes.", "evidence": "Logs and exercise evidence", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-10", "title": "Recovery and service continuity", "category": "Recover", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Demonstrate applicable recovery arrangements.", "evidence": "Restore and exercise results", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-11", "title": "Additional classification controls", "category": "Scope", "kind": "readiness", "mandatory": false, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Add applicable cloud, software, network, managed-service or OT controls.", "evidence": "Mapped technical evidence", "source_url": "https://www.aramco.com/-/media/downloads/working-with-us/ccc/sacs-210-third-party-cybersecurity-standard.pdf"}, {"key": "aramco-ccc-plus-12", "title": "Authorised audit firm engagement", "category": "Assessment", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Verify the firm against Aramco’s current authorised list and agree the assessment scope.", "evidence": "Engagement and authorisation check", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "aramco-ccc-plus-13", "title": "On-site assessment preparation", "category": "Assessment", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Arrange site access, staff availability and evidence access with the appointed assessor.", "evidence": "Agreed on-site assessment plan", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "aramco-ccc-plus-14", "title": "Assessor findings and closure", "category": "Assessment", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Record the actual findings; obtain assessor confirmation of the outcome.", "evidence": "Assessor findings and closure record", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "aramco-ccc-plus-15", "title": "Issued CCC+ certificate and report", "category": "Certification", "kind": "certification", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Record the authorised firm’s issued CCC+ and report; preparation never counts as issuance.", "evidence": "CCC+ certificate, report, scope, issuer and expiry", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "aramco-ccc-plus-16", "title": "Submission and renewal", "category": "Maintenance", "kind": "readiness", "mandatory": true, "applies_when": "Confirmed CCC+ engagement; technical controls follow the agreed classification and scope.", "guidance": "Record submission and track expiry and scope changes.", "evidence": "Submission receipt and renewal plan", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}]');
INSERT INTO public.procurement_packs(id,version,title,description,caution,source_checked_on,requirements) VALUES ('uk-government','2026-09-16.1','UK government procurement','Prepare a supplier record and the evidence requested by the specific UK public-sector buyer.','Choose the applicable procurement regime, including Scotland and transitional procurements. Registration does not confer universal approval. Tender requirements take precedence.','2026-09-16','[{"key": "uk-government-01", "title": "Procurement regime and tender scope", "category": "Scope", "kind": "readiness", "applies_when": "Every target opportunity", "guidance": "Identify the authority, jurisdiction, procurement date and applicable regime.", "evidence": "Tender reference and scope decision", "source_url": "https://www.gov.uk/government/publications/procurement-act-2023-guidance-documents-plan-phase/guidance-devolved-contracting-authorities-html"}, {"key": "uk-government-02", "title": "Find a Tender supplier record", "category": "Registration", "kind": "registration", "applies_when": "Where the procurement uses the central digital platform", "guidance": "Prepare the organisation record and confirm the current sharing process.", "evidence": "Supplier identifier and dated registration confirmation", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-03", "title": "Ownership and exclusion declarations", "category": "Eligibility", "kind": "readiness", "applies_when": "As required by the procurement", "guidance": "Review connected persons, exclusion questions and supporting records.", "evidence": "Approved declarations and ownership chart", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-04", "title": "Financial standing and insurance", "category": "Commercial", "kind": "readiness", "applies_when": "According to the tender and contract stage", "guidance": "Record the requested financial evidence and insurance limits; confirm when cover must be held.", "evidence": "Accounts, financial review and insurance evidence", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-05", "title": "Cyber Essentials scope", "category": "Security", "kind": "certification", "applies_when": "Where the buyer requires Cyber Essentials or Plus", "guidance": "Confirm the current scheme and covered systems. Record an issued certificate only after assessment.", "evidence": "Certificate, scope and expiry date", "source_url": "https://www.ncsc.gov.uk/cyberessentials/resources"}, {"key": "uk-government-06", "title": "Privacy and information handling", "category": "Data", "kind": "readiness", "applies_when": "Where the service processes protected or personal information", "guidance": "Map data flows, hosting, retention and the buyer’s contractual protections.", "evidence": "Data map and approved contractual response", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-07", "title": "Quality, safety and professional competence", "category": "Delivery", "kind": "readiness", "applies_when": "Where specified for the service or goods", "guidance": "List required standards, licences, staff qualifications and relevant experience.", "evidence": "Scoped certificates, qualifications and references", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-08", "title": "Social value and environmental commitments", "category": "Sustainability", "kind": "readiness", "applies_when": "Where included in the current procurement documents", "guidance": "Confirm current policy applicability, requested measures and reporting obligations.", "evidence": "Tender-specific commitments and delivery plan", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-09", "title": "Supply-chain and ethical requirements", "category": "Supply chain", "kind": "readiness", "applies_when": "Where required by law or contract", "guidance": "Review subcontractors, anti-bribery and modern-slavery obligations for this engagement.", "evidence": "Due diligence and policy evidence", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}, {"key": "uk-government-10", "title": "Tender-specific acceptance", "category": "Buyer decision", "kind": "buyer_decision", "applies_when": "Every bid or framework application", "guidance": "Record the buyer’s actual decision and its limits separately from preparation.", "evidence": "Buyer decision notice and reference", "source_url": "https://www.gov.uk/government/collections/information-and-guidance-for-suppliers"}]');
INSERT INTO public.procurement_packs(id,version,title,description,caution,source_checked_on,requirements) VALUES ('saudi-aramco','2026-09-16.1','Saudi Aramco supplier readiness','Prepare registration, supplier classification, cybersecurity evidence and assessor handover.','Use the registration route for the supplier’s location and the current Aramco classification. The CCC page differs between its table and FAQ for Network Connectivity: confirm CCC/CCC+ with Aramco or an authorised assessor. This pack is not the full SACS-210 control set.','2026-09-16','[{"key": "saudi-aramco-01", "title": "Supplier location and registration route", "category": "Scope", "kind": "readiness", "applies_when": "Every supplier", "guidance": "Confirm the Aramco entity and location-specific onboarding route.", "evidence": "Documented route and supplier scope", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier"}, {"key": "saudi-aramco-02", "title": "Entity and statutory records", "category": "Registration", "kind": "registration", "applies_when": "According to the applicable regional registration checklist", "guidance": "Collect current incorporation, ownership, tax and other requested records.", "evidence": "Regional checklist and current records", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier"}, {"key": "saudi-aramco-03", "title": "Authorised contacts and business profile", "category": "Registration", "kind": "readiness", "applies_when": "As requested during onboarding", "guidance": "Prepare signatory authority, bank relationship and company profile evidence.", "evidence": "Authorisation and company records", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier"}, {"key": "saudi-aramco-04", "title": "Supplier code and conduct", "category": "Governance", "kind": "readiness", "applies_when": "As required by the onboarding process", "guidance": "Arrange acknowledgement and supporting internal responsibilities.", "evidence": "Code acknowledgement and owner", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier"}, {"key": "saudi-aramco-05", "title": "Third-party classification confirmation", "category": "Cybersecurity", "kind": "readiness", "applies_when": "Aramco third-party cybersecurity assessment", "guidance": "Obtain the proponent classification and confirm the applicable assessment route.", "evidence": "Classification template and confirmation letter", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "saudi-aramco-06", "title": "SACS-210 control implementation", "category": "Cybersecurity", "kind": "readiness", "applies_when": "Controls applicable to confirmed classification", "guidance": "Add each applicable current control as a buyer-specific requirement and close evidence gaps.", "evidence": "Scoped control register and dated evidence", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "saudi-aramco-07", "title": "Authorised assessor and CCC / CCC+", "category": "Certification", "kind": "certification", "applies_when": "According to confirmed classification", "guidance": "Use an authorised audit firm; record the issued certificate and its scope.", "evidence": "Issued certificate and compliance report", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "saudi-aramco-08", "title": "Local content and technical qualification", "category": "Qualification", "kind": "readiness", "applies_when": "Where required for the supplier category or contract", "guidance": "Confirm applicable local-content, technical, quality and safety requirements with the buyer.", "evidence": "Buyer requirements and qualification evidence", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier"}, {"key": "saudi-aramco-09", "title": "Certificate renewal and scope change", "category": "Maintenance", "kind": "readiness", "applies_when": "After certification and when services change", "guidance": "Track expiry; obtain assessor advice when the classification changes.", "evidence": "Renewal plan and scope-change review", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/supplier-resources/cybersecurity-compliance-certificate-program"}, {"key": "saudi-aramco-10", "title": "Aramco qualification decision", "category": "Buyer decision", "kind": "buyer_decision", "applies_when": "When registration or qualification is decided", "guidance": "Record the actual decision; registration and qualification do not promise an order.", "evidence": "Supplier reference and buyer decision", "source_url": "https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier"}]');
INSERT INTO public.procurement_packs(id,version,title,description,caution,source_checked_on,requirements) VALUES ('us-federal','2026-09-16.1','US federal procurement','Prepare federal supplier registration and a contract-specific compliance matrix.','Federal requirements vary by agency, solicitation, data and prime/subcontractor role. Check current FAR/DFARS clauses and deviations. CMMC, FedRAMP and export controls are conditional, not universal badges.','2026-09-16','[{"key": "us-federal-01", "title": "Agency, solicitation and supplier role", "category": "Scope", "kind": "readiness", "applies_when": "Every target opportunity", "guidance": "Identify agency, scope, prime/subcontractor role and incorporated requirements.", "evidence": "Solicitation and clause register", "source_url": "https://www.acquisition.gov/browse/index/far"}, {"key": "us-federal-02", "title": "SAM registration and Unique Entity ID", "category": "Registration", "kind": "registration", "applies_when": "Where federal award rules require registration", "guidance": "Confirm active registration, entity validation and renewal obligations.", "evidence": "Entity registration and identifier", "source_url": "https://sam.gov/entity-registration"}, {"key": "us-federal-03", "title": "Representations and certifications", "category": "Eligibility", "kind": "readiness", "applies_when": "As required by the solicitation", "guidance": "Have an authorised officer review the applicable representations.", "evidence": "Dated submitted representations", "source_url": "https://www.acquisition.gov/browse/index/far"}, {"key": "us-federal-04", "title": "Exclusions, responsibility and eligibility", "category": "Eligibility", "kind": "readiness", "applies_when": "As required by the procurement", "guidance": "Verify exclusions, restrictions and any claimed programme eligibility.", "evidence": "Dated checks and eligibility evidence", "source_url": "https://sam.gov/entity-registration"}, {"key": "us-federal-05", "title": "Federal information safeguarding", "category": "Security", "kind": "readiness", "applies_when": "Where contract clauses cover federal information", "guidance": "Classify the information and map the safeguards required by the actual clauses.", "evidence": "Data scope and implementation evidence", "source_url": "https://www.acquisition.gov/browse/index/far"}, {"key": "us-federal-06", "title": "DoD cyber and CMMC assessment route", "category": "Security", "kind": "certification", "applies_when": "Where applicable DoD clauses require it", "guidance": "Confirm the current clause, deviation and assessment route before claiming status. Do not assume a rollout deadline.", "evidence": "Scoped assessment record and required affirmation", "source_url": "https://www.acq.osd.mil/dpap/dars/dfars_far_overhaul_class_deviations.html"}, {"key": "us-federal-07", "title": "Federal cloud security status", "category": "Cloud", "kind": "certification", "applies_when": "Cloud services within the current FedRAMP scope", "guidance": "Confirm the offering’s own applicable status; a hosting provider’s status does not automatically cover the application.", "evidence": "Official offering record and boundary", "source_url": "https://www.fedramp.gov/2026/scope/"}, {"key": "us-federal-08", "title": "Supply-chain, origin and export restrictions", "category": "Supply chain", "kind": "readiness", "applies_when": "Where incorporated or legally applicable", "guidance": "Review sourcing, restricted equipment, country-of-origin and export requirements.", "evidence": "Product provenance and specialist review", "source_url": "https://www.acquisition.gov/browse/index/far"}, {"key": "us-federal-09", "title": "Labour, accessibility and subcontract flow-downs", "category": "Delivery", "kind": "readiness", "applies_when": "Where the solicitation requires them", "guidance": "Map the obligations applying to the workforce, deliverables and subcontractors.", "evidence": "Clause response and subcontract matrix", "source_url": "https://www.acquisition.gov/browse/index/far"}, {"key": "us-federal-10", "title": "Agency award or acceptance", "category": "Buyer decision", "kind": "buyer_decision", "applies_when": "When the agency issues a decision", "guidance": "Record the actual procurement decision and scope. SAM registration alone is not approval.", "evidence": "Agency decision and contract reference", "source_url": "https://sam.gov/entity-registration"}]');
INSERT INTO public.procurement_packs(id,version,title,description,caution,source_checked_on,requirements) VALUES ('investment-banking','2026-09-16.1','Investment-bank supplier readiness','Prepare for bank vendor onboarding, security questionnaires and third-party due diligence.','This pack covers supplying services to banks, not authorisation to conduct regulated investment banking. Each bank has its own due diligence and contract. ISO certificates and SOC reports support review but do not establish universal bank approval.','2026-09-16','[{"key": "investment-banking-01", "title": "Bank, service and risk classification", "category": "Scope", "kind": "readiness", "applies_when": "Every bank engagement", "guidance": "Confirm service scope, jurisdictions, access and criticality with procurement.", "evidence": "Buyer questionnaire and service boundary", "source_url": "https://www.goldmansachs.com/our-firm/our-vendor-program"}, {"key": "investment-banking-02", "title": "Corporate, financial and ethical due diligence", "category": "Governance", "kind": "readiness", "applies_when": "As requested by the bank", "guidance": "Prepare ownership, financial, sanctions, conflicts and supplier-conduct evidence.", "evidence": "Reviewed corporate due-diligence pack", "source_url": "https://www.goldmansachs.com/our-firm/our-vendor-program"}, {"key": "investment-banking-03", "title": "Information-security control response", "category": "Security", "kind": "readiness", "applies_when": "For systems and information in the bank’s scope", "guidance": "Map buyer controls to operating evidence and accountable owners.", "evidence": "Completed control matrix", "source_url": "https://jpmorganchase.com/supplierdiversity/oversight"}, {"key": "investment-banking-04", "title": "Identity, access and personnel controls", "category": "Security", "kind": "readiness", "applies_when": "For relevant staff and system access", "guidance": "Document access reviews, onboarding, screening and training required by the bank.", "evidence": "Access and personnel control evidence", "source_url": "https://jpmorganchase.com/supplierdiversity/oversight"}, {"key": "investment-banking-05", "title": "Testing, vulnerability and incident response", "category": "Security", "kind": "readiness", "applies_when": "As required by the bank’s service scope", "guidance": "Prepare test findings, remediation and incident-handling evidence.", "evidence": "Test report and incident plan", "source_url": "https://jpmorganchase.com/supplierdiversity/oversight"}, {"key": "investment-banking-06", "title": "Privacy, hosting and subcontractors", "category": "Data", "kind": "readiness", "applies_when": "Where bank information or delegated services are involved", "guidance": "Disclose data locations and subcontractors; confirm buyer consent and protections.", "evidence": "Data-flow and subcontractor register", "source_url": "https://jpmorganchase.com/supplierdiversity/oversight"}, {"key": "investment-banking-07", "title": "Continuity, recovery and exit", "category": "Resilience", "kind": "readiness", "applies_when": "According to service criticality and contract", "guidance": "Prepare tested recovery and an executable exit approach.", "evidence": "Exercise results and exit plan", "source_url": "https://jpmorganchase.com/supplierdiversity/oversight"}, {"key": "investment-banking-08", "title": "Independent assurance evidence", "category": "Assurance", "kind": "certification", "applies_when": "Where the buyer asks for ISO, SOC or other assurance", "guidance": "Record the actual issuer, period, scope and exceptions. SOC 2 is an attestation report.", "evidence": "Scoped certificate or assurance report", "source_url": "https://www.goldmansachs.com/our-firm/our-vendor-program"}, {"key": "investment-banking-09", "title": "AI service disclosure and governance", "category": "AI", "kind": "readiness", "applies_when": "When providing AI-enabled services", "guidance": "Confirm the bank’s AI provider requirements and document intended use and oversight.", "evidence": "AI inventory and buyer-specific response", "source_url": "https://www.jpmorganchase.com/about/suppliers"}, {"key": "investment-banking-10", "title": "Bank onboarding and acceptance decision", "category": "Buyer decision", "kind": "buyer_decision", "applies_when": "When the bank completes its review", "guidance": "Record only the bank’s actual acceptance for the defined entity and service.", "evidence": "Written acceptance and vendor reference", "source_url": "https://www.goldmansachs.com/our-firm/our-vendor-program"}]');

COMMIT;
